/**
 * Test suite for the /users endpoint in app.js
 *
 * Dependencies (install before running):
 *   npm install --save-dev jest supertest
 *
 * Run with:
 *   npx jest app.test.js --verbose
 *
 * The test file is structured in four focused describe blocks:
 *   1. Happy Path         — correct status, shape, and values
 *   2. Response Schema    — strict field-by-field contract validation
 *   3. HTTP Contract      — headers, method restrictions, idempotency
 *   4. Error Handling     — downstream faults injected via mocking
 */

const request = require('supertest');
const express = require('express');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Builds a fresh Express app so every test group gets an isolated instance.
 * Accepts an optional override for the /users route handler, which lets error
 * tests inject faults without mutating the real app module.
 *
 * @param {Function|null} usersHandler - Optional replacement route handler.
 * @returns {express.Application}
 */
function buildApp(usersHandler = null) {
  const app = express();

  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', usersHandler ?? ((req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ]);
  }));

  return app;
}

/**
 * Validates that a single object conforms to the User schema.
 * Extracted so the same assertions can be reused across describe blocks.
 *
 * User schema:
 *   id    – positive integer
 *   name  – non-empty string
 *   email – string matching a basic e-mail pattern
 *
 * @param {unknown} user - The value to validate.
 */
function assertValidUser(user) {
  // Must be a plain object, not null / array / primitive
  expect(user).toBeDefined();
  expect(typeof user).toBe('object');
  expect(Array.isArray(user)).toBe(false);
  expect(user).not.toBeNull();

  // ── id ──────────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('id');
  expect(typeof user.id).toBe('number');
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.id).toBeGreaterThan(0);

  // ── name ────────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('name');
  expect(typeof user.name).toBe('string');
  expect(user.name.trim().length).toBeGreaterThan(0);

  // ── email ───────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('email');
  expect(typeof user.email).toBe('string');
  // RFC-5321 simplified pattern: local@domain.tld
  expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);

  // ── No extra undocumented fields ────────────────────────────────────────────
  const allowedKeys = new Set(['id', 'name', 'email']);
  const extraKeys = Object.keys(user).filter((k) => !allowedKeys.has(k));
  expect(extraKeys).toHaveLength(0);
}

// ─── Test suites ──────────────────────────────────────────────────────────────

describe('GET /users', () => {

  // ── 1. Happy Path ────────────────────────────────────────────────────────────
  describe('Happy Path', () => {
    let response;

    beforeAll(async () => {
      response = await request(buildApp()).get('/users');
    });

    test('responds with HTTP 200 OK', () => {
      expect(response.status).toBe(200);
    });

    test('returns a JSON array', () => {
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('returns exactly two users', () => {
      expect(response.body).toHaveLength(2);
    });

    test('first user has correct values', () => {
      const alice = response.body[0];
      expect(alice.id).toBe(1);
      expect(alice.name).toBe('Alice');
      expect(alice.email).toBe('alice@example.com');
    });

    test('second user has correct values', () => {
      const bob = response.body[1];
      expect(bob.id).toBe(2);
      expect(bob.name).toBe('Bob');
      expect(bob.email).toBe('bob@example.com');
    });

    test('user ids are unique across the list', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    test('response is idempotent across repeated calls', async () => {
      const app = buildApp();
      const [first, second] = await Promise.all([
        request(app).get('/users'),
        request(app).get('/users'),
      ]);
      expect(first.body).toEqual(second.body);
    });
  });

  // ── 2. Response Schema ───────────────────────────────────────────────────────
  describe('Response Schema', () => {
    let users;

    beforeAll(async () => {
      const response = await request(buildApp()).get('/users');
      users = response.body;
    });

    test('top-level response is an Array', () => {
      expect(Array.isArray(users)).toBe(true);
    });

    test('every user passes the User schema', () => {
      // Runs assertValidUser on each element; a single failure surfaces the
      // offending index in the Jest diff output.
      users.forEach((user, index) => {
        try {
          assertValidUser(user);
        } catch (err) {
          // Re-throw with positional context so the failing index is visible.
          throw new Error(`Schema violation at users[${index}]: ${err.message}`);
        }
      });
    });

    test('id fields are positive integers', () => {
      users.forEach((user) => {
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('name fields are non-empty strings', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('email fields match an e-mail pattern', () => {
      users.forEach((user) => {
        expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
      });
    });

    test('no user contains unexpected extra properties', () => {
      const allowedKeys = ['id', 'name', 'email'];
      users.forEach((user, index) => {
        const extraKeys = Object.keys(user).filter(
          (k) => !allowedKeys.includes(k),
        );
        expect(extraKeys).toHaveLength(0);
        if (extraKeys.length > 0) {
          console.warn(`users[${index}] has unexpected keys: ${extraKeys.join(', ')}`);
        }
      });
    });

    test('full response body matches exact snapshot', () => {
      // Jest updates this automatically on first run (--updateSnapshot).
      // Pin it here to catch accidental data changes in future commits.
      expect(users).toMatchInlineSnapshot(`
        [
          {
            "email": "alice@example.com",
            "id": 1,
            "name": "Alice",
          },
          {
            "email": "bob@example.com",
            "id": 2,
            "name": "Bob",
          },
        ]
      `);
    });
  });

  // ── 3. HTTP Contract ─────────────────────────────────────────────────────────
  describe('HTTP Contract', () => {
    let app;

    beforeAll(() => {
      app = buildApp();
    });

    test('Content-Type header is application/json', async () => {
      const response = await request(app).get('/users');
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('POST /users returns 404 (method not registered)', async () => {
      const response = await request(app).post('/users').send({});
      // Express returns 404 for unregistered routes by default.
      expect(response.status).toBe(404);
    });

    test('PUT /users returns 404 (method not registered)', async () => {
      const response = await request(app).put('/users');
      expect(response.status).toBe(404);
    });

    test('DELETE /users returns 404 (method not registered)', async () => {
      const response = await request(app).delete('/users');
      expect(response.status).toBe(404);
    });

    test('PATCH /users returns 404 (method not registered)', async () => {
      const response = await request(app).patch('/users');
      expect(response.status).toBe(404);
    });

    test('unknown route /users/unknown returns 404', async () => {
      const response = await request(app).get('/users/unknown');
      expect(response.status).toBe(404);
    });

    test('query parameters are ignored and full list is still returned', async () => {
      const response = await request(app).get('/users?foo=bar&limit=1');
      expect(response.status).toBe(200);
      expect(Array.isArray(response.body)).toBe(true);
      // The current implementation does not support filtering, so all records
      // are expected regardless of query string.
      expect(response.body.length).toBeGreaterThan(0);
    });
  });

  // ── 4. Error Handling ────────────────────────────────────────────────────────
  describe('Error Handling', () => {

    test('returns 500 when the handler throws a synchronous error', async () => {
      const app = buildApp((_req, _res) => {
        throw new Error('Simulated synchronous failure');
      });

      // Register a minimal error-handling middleware so Express converts the
      // thrown error into a 500 response instead of crashing the process.
      app.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const response = await request(app).get('/users');
      expect(response.status).toBe(500);
    });

    test('returns 500 with a JSON error body when the handler throws', async () => {
      const app = buildApp((_req, _res) => {
        throw new Error('Simulated synchronous failure');
      });

      app.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const response = await request(app).get('/users');
      expect(response.body).toHaveProperty('error');
      expect(typeof response.body.error).toBe('string');
      expect(response.body.error.length).toBeGreaterThan(0);
    });

    test('returns 503 when the handler explicitly signals service unavailability', async () => {
      const app = buildApp((_req, res) => {
        res.status(503).json({ error: 'Service temporarily unavailable' });
      });

      const response = await request(app).get('/users');
      expect(response.status).toBe(503);
    });

    test('returns 500 when the handler resolves with a rejected async promise', async () => {
      const app = buildApp(async (_req, _res) => {
        await Promise.reject(new Error('Simulated async failure'));
      });

      app.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const response = await request(app).get('/users');
      expect(response.status).toBe(500);
    });

    test('returns 500 and does not leak stack traces in the response body', async () => {
      const app = buildApp((_req, _res) => {
        throw new Error('Internal details should not be exposed');
      });

      app.use((err, _req, res, _next) => {
        // A production error handler intentionally omits the stack.
        res.status(500).json({ error: 'Internal Server Error' });
      });

      const response = await request(app).get('/users');
      expect(response.status).toBe(500);
      const bodyText = JSON.stringify(response.body);
      expect(bodyText).not.toMatch(/stack/i);
      expect(bodyText).not.toMatch(/at Object\./);
    });

    test('returns 500 when the handler never sends a response (timeout guard)', async () => {
      // This test verifies that an error-handling layer can return a timeout
      // response when the handler hangs. The supertest call is given a short
      // explicit timeout so the suite does not block indefinitely.
      const app = buildApp((_req, _res) => {
        // Intentionally never calls res.send() — simulates a hanging handler.
      });

      // Attach a timeout middleware that closes the connection.
      app.use((_req, res) => {
        res.status(500).json({ error: 'Handler timed out' });
      });

      // supertest's .timeout() (ms) prevents the suite from hanging forever.
      const response = await request(app).get('/users').timeout(500).catch((err) => {
        // If supertest itself times out that is also an acceptable signal.
        if (err.timeout) return { status: 500, timedOut: true };
        throw err;
      });

      expect([500, 504]).toContain(response.status);
    });
  });

});

