/**
 * Test suite for app.js — /users endpoint
 *
 * Coverage areas:
 *  1. Happy path          – correct status, body shape, and field values
 *  2. Response schema     – every field of every user object is validated
 *  3. Error / edge cases  – wrong method, wrong path, unsupported content negotiation
 */

const request = require('supertest');
const app = require('./app');

// ─── Schema validator ────────────────────────────────────────────────────────
// Validates that a single user object matches the expected shape and types.
// Returns an object with `valid: boolean` and a human-readable `errors` array.
function validateUserSchema(user) {
  const errors = [];

  if (typeof user !== 'object' || user === null || Array.isArray(user)) {
    errors.push('user must be a non-null object');
    return { valid: false, errors };
  }

  // id — required, positive integer
  if (!Object.prototype.hasOwnProperty.call(user, 'id')) {
    errors.push('missing field: id');
  } else if (typeof user.id !== 'number' || !Number.isInteger(user.id) || user.id <= 0) {
    errors.push(`id must be a positive integer, got: ${JSON.stringify(user.id)}`);
  }

  // name — required, non-empty string
  if (!Object.prototype.hasOwnProperty.call(user, 'name')) {
    errors.push('missing field: name');
  } else if (typeof user.name !== 'string' || user.name.trim() === '') {
    errors.push(`name must be a non-empty string, got: ${JSON.stringify(user.name)}`);
  }

  // email — required, string matching a basic e-mail pattern
  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!Object.prototype.hasOwnProperty.call(user, 'email')) {
    errors.push('missing field: email');
  } else if (typeof user.email !== 'string' || !EMAIL_RE.test(user.email)) {
    errors.push(`email must be a valid e-mail address, got: ${JSON.stringify(user.email)}`);
  }

  // No unexpected extra fields
  const ALLOWED_KEYS = new Set(['id', 'name', 'email']);
  Object.keys(user).forEach((key) => {
    if (!ALLOWED_KEYS.has(key)) {
      errors.push(`unexpected field: ${key}`);
    }
  });

  return { valid: errors.length === 0, errors };
}

// ─── Test suite ──────────────────────────────────────────────────────────────

describe('GET /users', () => {

  // ── 1. Happy path ──────────────────────────────────────────────────────────

  describe('happy path', () => {
    let response;

    beforeAll(async () => {
      response = await request(app).get('/users');
    });

    test('responds with HTTP 200', () => {
      expect(response.status).toBe(200);
    });

    test('Content-Type header is application/json', () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('response body is an array', () => {
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('returns exactly 2 users', () => {
      expect(response.body).toHaveLength(2);
    });

    test('first user has the correct field values', () => {
      const alice = response.body[0];
      expect(alice).toEqual({
        id: 1,
        name: 'Alice',
        email: 'alice@example.com',
      });
    });

    test('second user has the correct field values', () => {
      const bob = response.body[1];
      expect(bob).toEqual({
        id: 2,
        name: 'Bob',
        email: 'bob@example.com',
      });
    });

    test('user ids are unique across the list', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    test('user names are unique across the list', () => {
      const names = response.body.map((u) => u.name);
      const uniqueNames = new Set(names);
      expect(uniqueNames.size).toBe(names.length);
    });

    test('user emails are unique across the list', () => {
      const emails = response.body.map((u) => u.email);
      const uniqueEmails = new Set(emails);
      expect(uniqueEmails.size).toBe(emails.length);
    });
  });

  // ── 2. Response schema validation ─────────────────────────────────────────

  describe('response schema', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get('/users');
      users = response.body;
    });

    test('every user passes the schema validator', () => {
      users.forEach((user, index) => {
        const { valid, errors } = validateUserSchema(user);
        expect(valid, `user[${index}] schema errors: ${errors.join(', ')}`).toBe(true);
      });
    });

    test('id field is a positive integer on every user', () => {
      users.forEach((user, index) => {
        expect(
          typeof user.id === 'number' && Number.isInteger(user.id) && user.id > 0,
          `user[${index}].id failed — value: ${user.id}`
        ).toBe(true);
      });
    });

    test('name field is a non-empty string on every user', () => {
      users.forEach((user, index) => {
        expect(typeof user.name, `user[${index}].name type`).toBe('string');
        expect(user.name.trim().length, `user[${index}].name is empty`).toBeGreaterThan(0);
      });
    });

    test('email field is a valid e-mail string on every user', () => {
      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      users.forEach((user, index) => {
        expect(typeof user.email, `user[${index}].email type`).toBe('string');
        expect(
          EMAIL_RE.test(user.email),
          `user[${index}].email is not a valid address — value: ${user.email}`
        ).toBe(true);
      });
    });

    test('no user object contains unexpected extra fields', () => {
      const ALLOWED_KEYS = ['id', 'name', 'email'];
      users.forEach((user, index) => {
        const extraKeys = Object.keys(user).filter((k) => !ALLOWED_KEYS.includes(k));
        expect(
          extraKeys,
          `user[${index}] has unexpected keys: ${extraKeys.join(', ')}`
        ).toHaveLength(0);
      });
    });

    test('response body matches the full expected snapshot', () => {
      expect(users).toMatchInlineSnapshot(`
        [
          {
            "email": "alice@example.com",
            "id": 1,
            "name": "Alice",
          },
          {
            "email": "bob@example.com",
            "id": 2,
            "name": "Bob",
          },
        ]
      `);
    });
  });

  // ── 3. Error handling & edge cases ────────────────────────────────────────

  describe('error handling and edge cases', () => {

    test('POST /users returns 404 (method not supported)', async () => {
      const response = await request(app).post('/users').send({ name: 'Eve' });
      // Express returns 404 for unregistered method+path combinations
      expect(response.status).toBe(404);
    });

    test('PUT /users returns 404 (method not supported)', async () => {
      const response = await request(app).put('/users');
      expect(response.status).toBe(404);
    });

    test('DELETE /users returns 404 (method not supported)', async () => {
      const response = await request(app).delete('/users');
      expect(response.status).toBe(404);
    });

    test('PATCH /users returns 404 (method not supported)', async () => {
      const response = await request(app).patch('/users');
      expect(response.status).toBe(404);
    });

    test('GET /users/ (trailing slash) returns 404', async () => {
      // Express strict routing is off by default; a trailing slash still does
      // not match the registered "/users" route, so it falls through.
      const response = await request(app).get('/users/');
      expect(response.status).toBe(404);
    });

    test('GET /user (singular) returns 404 — only plural route is defined', async () => {
      const response = await request(app).get('/user');
      expect(response.status).toBe(404);
    });

    test('GET /USERS (uppercase) returns 404 — routes are case-sensitive', async () => {
      const response = await request(app).get('/USERS');
      expect(response.status).toBe(404);
    });

    test('GET /users?foo=bar ignores unknown query params and returns 200', async () => {
      const response = await request(app).get('/users?foo=bar');
      expect(response.status).toBe(200);
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('GET /users does not set a Set-Cookie header (no session leakage)', async () => {
      const response = await request(app).get('/users');
      expect(response.headers['set-cookie']).toBeUndefined();
    });

    test('GET /users without Accept header still returns JSON', async () => {
      const response = await request(app)
        .get('/users')
        .set('Accept', '*/*');
      expect(response.status).toBe(200);
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('response body is not an empty array (data is always seeded)', async () => {
      const response = await request(app).get('/users');
      expect(response.body.length).toBeGreaterThan(0);
    });
  });
});

// ─── Sanity-check the schema validator itself ─────────────────────────────────

describe('validateUserSchema (internal helper)', () => {
  test('accepts a fully valid user object', () => {
    const { valid } = validateUserSchema({ id: 1, name: 'Alice', email: 'alice@example.com' });
    expect(valid).toBe(true);
  });

  test('rejects a user with a missing id', () => {
    const { valid, errors } = validateUserSchema({ name: 'Alice', email: 'alice@example.com' });
    expect(valid).toBe(false);
    expect(errors).toContain('missing field: id');
  });

  test('rejects a user with a non-integer id', () => {
    const { valid, errors } = validateUserSchema({ id: 'one', name: 'Alice', email: 'alice@example.com' });
    expect(valid).toBe(false);
    expect(errors.some((e) => e.startsWith('id must be'))).toBe(true);
  });

  test('rejects a user with a negative id', () => {
    const { valid, errors } = validateUserSchema({ id: -5, name: 'Alice', email: 'alice@example.com' });
    expect(valid).toBe(false);
    expect(errors.some((e) => e.startsWith('id must be'))).toBe(true);
  });

  test('rejects a user with an empty name', () => {
    const { valid, errors } = validateUserSchema({ id: 1, name: '  ', email: 'alice@example.com' });
    expect(valid).toBe(false);
    expect(errors.some((e) => e.startsWith('name must be'))).toBe(true);
  });

  test('rejects a user with a missing email', () => {
    const { valid, errors } = validateUserSchema({ id: 1, name: 'Alice' });
    expect(valid).toBe(false);
    expect(errors).toContain('missing field: email');
  });

  test('rejects a user with a malformed email', () => {
    const { valid, errors } = validateUserSchema({ id: 1, name: 'Alice', email: 'not-an-email' });
    expect(valid).toBe(false);
    expect(errors.some((e) => e.startsWith('email must be'))).toBe(true);
  });

  test('rejects a user object with unexpected extra fields', () => {
    const { valid, errors } = validateUserSchema({ id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' });
    expect(valid).toBe(false);
    expect(errors).toContain('unexpected field: role');
  });

  test('rejects null as a user', () => {
    const { valid } = validateUserSchema(null);
    expect(valid).toBe(false);
  });

  test('rejects an array as a user', () => {
    const { valid } = validateUserSchema([]);
    expect(valid).toBe(false);
  });
});

