// ═══════════════════════════════════════════════════════════════════════════════
// 1.  Happy-path tests
// ═══════════════════════════════════════════════════════════════════════════════

describe('GET /users — happy path', () => {

  test('responds with HTTP 200', async () => {
    const res = await request(app).get('/users');
    expect(res.status).toBe(200);
  });

  test('sets Content-Type to application/json', async () => {
    const res = await request(app).get('/users');
    expect(res.headers['content-type']).toMatch(/application\/json/);
  });

  test('returns a non-empty array', async () => {
    const res = await request(app).get('/users');
    expect(Array.isArray(res.body)).toBe(true);
    expect(res.body.length).toBeGreaterThan(0);
  });

  test('returns the exact seeded users', async () => {
    const res = await request(app).get('/users');
    expect(res.body).toEqual([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ]);
  });

  test('each user has a unique id', async () => {
    const res = await request(app).get('/users');
    const ids = res.body.map(u => u.id);
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  test('each user email is unique', async () => {
    const res = await request(app).get('/users');
    const emails = res.body.map(u => u.email);
    const uniqueEmails = new Set(emails);
    expect(uniqueEmails.size).toBe(emails.length);
  });

  test('handles HEAD request without a body', async () => {
    const res = await request(app).head('/users');
    // HEAD must mirror GET status and headers, but carry no body
    expect(res.status).toBe(200);
    expect(res.headers['content-type']).toMatch(/application\/json/);
    expect(res.text).toBeFalsy();
  });

  test('responds consistently across multiple sequential calls (idempotency)', async () => {
    const [first, second, third] = await Promise.all([
      request(app).get('/users'),
      request(app).get('/users'),
      request(app).get('/users'),
    ]);

    expect(first.body).toEqual(second.body);
    expect(second.body).toEqual(third.body);
  });

});

