// 2.  Error-handling tests
// ═══════════════════════════════════════════════════════════════════════════════

describe('GET /users — error handling', () => {

  test('POST /users returns 404 (method not allowed / not found)', async () => {
    const res = await request(app).post('/users').send({ name: 'Eve' });
    // Express returns 404 for unregistered method+path combinations by default
    expect(res.status).toBe(404);
  });

  test('PUT /users returns 404', async () => {
    const res = await request(app).put('/users');
    expect(res.status).toBe(404);
  });

  test('DELETE /users returns 404', async () => {
    const res = await request(app).delete('/users');
    expect(res.status).toBe(404);
  });

  test('unknown route /users/unknown returns 404', async () => {
    const res = await request(app).get('/users/unknown');
    expect(res.status).toBe(404);
  });

  test('unknown route /users/123 returns 404 (no dynamic :id route defined)', async () => {
    const res = await request(app).get('/users/123');
    expect(res.status).toBe(404);
  });

  test('query parameters are silently ignored and full list is still returned', async () => {
    const res = await request(app).get('/users?limit=1&offset=0&filter=Alice');
    // The current implementation ignores query params; response must still be valid
    expect(res.status).toBe(200);
    expect(Array.isArray(res.body)).toBe(true);
    expect(res.body.length).toBeGreaterThan(0);
  });

  describe('simulated handler errors', () => {
    /**
     * We temporarily replace the route handler with one that throws to verify
     * that Express's default error handling returns a 500-family status and does
     * NOT leak a stack trace in the body (important for production hardening).
     *
     * Strategy: override app._router.stack to splice in a failing handler,
     * then restore it after each sub-test.
     */

    let originalStack;

    beforeEach(() => {
      // Deep-clone the route stack reference so we can restore it
      originalStack = [...app._router.stack];
    });

    afterEach(() => {
      // Restore original stack to avoid polluting later tests
      app._router.stack = originalStack;
    });

    test('returns 500 when the /users handler throws a synchronous error', async () => {
      // Find the /users route layer and replace its handler with one that throws
      const usersLayer = app._router.stack.find(
        layer => layer.route && layer.route.path === '/users'
      );

      // Store the original dispatch so we can restore it
      const originalDispatch = usersLayer.route.stack[0].handle;

      usersLayer.route.stack[0].handle = (_req, _res, next) => {
        next(new Error('Simulated internal server error'));
      };

      // Express needs an error-handling middleware to convert the error to a 500.
      // Register a one-shot error handler for this test only.
      const errorHandler = (err, _req, res, _next) => {
        res.status(500).json({ error: 'Internal Server Error' });
      };
      app.use(errorHandler);

      const res = await request(app).get('/users');

      // Restore immediately after the request
      usersLayer.route.stack[0].handle = originalDispatch;
      // Remove the temporary error handler from the stack
      app._router.stack = app._router.stack.filter(l => l.handle !== errorHandler);

      expect(res.status).toBe(500);
      // Body must not expose raw stack traces
      const bodyStr = JSON.stringify(res.body);
      expect(bodyStr).not.toMatch(/Error:/);
      expect(bodyStr).not.toMatch(/at Object\./);
    });

    test('error response body does not leak sensitive file-system paths', async () => {
      const usersLayer = app._router.stack.find(
        layer => layer.route && layer.route.path === '/users'
      );
      const originalDispatch = usersLayer.route.stack[0].handle;

      usersLayer.route.stack[0].handle = (_req, _res, next) => {
        const err = new Error('DB connection failed at /var/app/db.js:42');
        next(err);
      };

      const errorHandler = (err, _req, res, _next) => {
        // Deliberately safe — only expose a generic message
        res.status(500).json({ error: 'Internal Server Error' });
      };
      app.use(errorHandler);

      const res = await request(app).get('/users');

      usersLayer.route.stack[0].handle = originalDispatch;
      app._router.stack = app._router.stack.filter(l => l.handle !== errorHandler);

      expect(res.status).toBe(500);
      expect(JSON.stringify(res.body)).not.toMatch(/\/var\/app/);
      expect(JSON.stringify(res.body)).not.toMatch(/db\.js/);
