// 3.  Response-schema validation tests
// ═══════════════════════════════════════════════════════════════════════════════

describe('GET /users — response schema', () => {

  let res; // shared response — fetched once for the whole describe block

  beforeAll(async () => {
    res = await request(app).get('/users');
  });

  // ── Top-level structure ──────────────────────────────────────────────────────

  test('top-level response body is an array', () => {
    expect(Array.isArray(res.body)).toBe(true);
  });

  test('array is not empty', () => {
    expect(res.body.length).toBeGreaterThan(0);
  });

  // ── Per-object field presence ────────────────────────────────────────────────

  test('every user has an "id" field', () => {
    res.body.forEach(user => {
      expect(user).toHaveProperty('id');
    });
  });

  test('every user has a "name" field', () => {
    res.body.forEach(user => {
      expect(user).toHaveProperty('name');
    });
  });

  test('every user has an "email" field', () => {
    res.body.forEach(user => {
      expect(user).toHaveProperty('email');
    });
  });

  // ── Per-object field types ───────────────────────────────────────────────────

  test('"id" is a positive integer for every user', () => {
    res.body.forEach(user => {
      expect(typeof user.id).toBe('number');
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });

  test('"name" is a non-empty string for every user', () => {
    res.body.forEach(user => {
      expect(typeof user.name).toBe('string');
      expect(user.name.trim().length).toBeGreaterThan(0);
    });
  });

  test('"email" is a valid email address string for every user', () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    res.body.forEach(user => {
      expect(typeof user.email).toBe('string');
      expect(emailRegex.test(user.email)).toBe(true);
    });
  });

  // ── No extra / unexpected fields ─────────────────────────────────────────────

  test('no user object contains unexpected extra fields', () => {
    const allowedKeys = ['id', 'name', 'email'];
    res.body.forEach(user => {
      const extraKeys = Object.keys(user).filter(k => !allowedKeys.includes(k));
      expect(extraKeys).toHaveLength(0);
    });
  });

  // ── Composite schema validator ────────────────────────────────────────────────

  test('every user passes the full validateUserSchema check', () => {
    res.body.forEach((user, index) => {
      const { valid, errors } = validateUserSchema(user);
      // Surface schema errors as a readable failure message
      expect(valid).toBe(true);
      if (!valid) {
        console.error(`Schema violations for user at index ${index}:`, errors);
      }
    });
  });

  // ── snapshot ─────────────────────────────────────────────────────────────────

  test('response body matches inline snapshot', () => {
    expect(res.body).toMatchInlineSnapshot(`
      [
        {
          "email": "alice@example.com",
          "id": 1,
          "name": "Alice",
        },
        {
          "email": "bob@example.com",
          "id": 2,
          "name": "Bob",
        },
      ]
    `);
  });

});

// ═══════════════════════════════════════════════════════════════════════════════
// 4.  Regression / boundary tests
// ═══════════════════════════════════════════════════════════════════════════════

describe('GET /users — regression & boundary', () => {

  test('no user id is 0 or negative', async () => {
    const res = await request(app).get('/users');
    res.body.forEach(user => {
      expect(user.id).toBeGreaterThan(0);
    });
  });

  test('no user name is only whitespace', async () => {
    const res = await request(app).get('/users');
    res.body.forEach(user => {
      expect(user.name.trim().length).toBeGreaterThan(0);
    });
  });

  test('no user email contains whitespace', async () => {
    const res = await request(app).get('/users');
    res.body.forEach(user => {
      expect(user.email).not.toMatch(/\s/);
    });
  });

  test('ids are stable across repeated requests (not randomly generated)', async () => {
    const [r1, r2] = await Promise.all([
      request(app).get('/users'),
      request(app).get('/users'),
    ]);
    const ids1 = r1.body.map(u => u.id);
    const ids2 = r2.body.map(u => u.id);
    expect(ids1).toEqual(ids2);
  });

  test('response is a valid JSON string (round-trip safe)', async () => {
    const res = await request(app).get('/users');
    const roundTripped = JSON.parse(JSON.stringify(res.body));
    expect(roundTripped).toEqual(res.body);
  });

});

