const request = require('supertest');
const app     = require('./app');

// ─── Schema helper ────────────────────────────────────────────────────────────

/**
 * Validates a single user object against the expected schema.
 *
 * Expected shape:
 *   { id: number, name: string, email: string }
 *
 * Returns an object { valid: boolean, errors: string[] } so individual
 * field failures surface clearly in test output.
 */
function validateUserSchema(user) {
  const errors = [];

  if (user === null || typeof user !== 'object' || Array.isArray(user)) {
    errors.push(`Expected a plain object but received ${Array.isArray(user) ? 'array' : typeof user}`);
    return { valid: false, errors };
  }

  // id — must be a positive integer
  if (!Object.prototype.hasOwnProperty.call(user, 'id')) {
    errors.push('Missing required field: id');
  } else if (typeof user.id !== 'number' || !Number.isInteger(user.id) || user.id <= 0) {
    errors.push(`Field 'id' must be a positive integer, got: ${JSON.stringify(user.id)}`);
  }

  // name — must be a non-empty string
  if (!Object.prototype.hasOwnProperty.call(user, 'name')) {
    errors.push('Missing required field: name');
  } else if (typeof user.name !== 'string' || user.name.trim() === '') {
    errors.push(`Field 'name' must be a non-empty string, got: ${JSON.stringify(user.name)}`);
  }

  // email — must be a string matching a basic email pattern
  if (!Object.prototype.hasOwnProperty.call(user, 'email')) {
    errors.push('Missing required field: email');
  } else if (typeof user.email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email)) {
    errors.push(`Field 'email' must be a valid email address, got: ${JSON.stringify(user.email)}`);
  }

  // No extra (unexpected) keys allowed
  const allowedKeys = new Set(['id', 'name', 'email']);
  const extraKeys   = Object.keys(user).filter(k => !allowedKeys.has(k));
  if (extraKeys.length > 0) {
    errors.push(`Unexpected field(s) in user object: ${extraKeys.join(', ')}`);
  }

  return { valid: errors.length === 0, errors };
}

