/**
 * app.test.js
 *
 * Unit / integration tests for the /users endpoint in app.js.
 *
 * Test suites
 * ───────────
 *  1. Happy path          – successful responses, status codes, payloads
 *  2. Response schema     – every field of every user object is validated
 *  3. Error handling      – 404 for unknown routes, wrong HTTP methods,
 *                           resilience when the route handler throws
 *  4. HTTP contract       – headers, content-type, caching semantics
 *
 * Dependencies
 * ────────────
 *   jest       – test runner & assertion library  (npm i -D jest)
 *   supertest  – HTTP integration layer            (npm i -D supertest)
 *
 * Run
 * ───
 *   npm test                  (standard)
 *   npm run test:verbose      (with per-test labels)
 *   npm run test:coverage     (with coverage report)
 */

const request = require('supertest');
const app = require('./app');

// ─── helpers ────────────────────────────────────────────────────────────────

/**
 * Expected schema for a single user object.
 * Used in schema-validation tests and shared assertion helpers.
 */
const USER_SCHEMA = {
  id: 'number',
  name: 'string',
  email: 'string',
};

/**
 * Assert that a value conforms to USER_SCHEMA.
 * Throws a descriptive Jest failure when any field is wrong.
 *
 * @param {unknown} user - Value to validate.
 */
function assertUserSchema(user) {
  // Must be a plain, non-null object
  expect(user).not.toBeNull();
  expect(typeof user).toBe('object');
  expect(Array.isArray(user)).toBe(false);

  // Every key in the schema must be present with the correct primitive type
  Object.entries(USER_SCHEMA).forEach(([field, expectedType]) => {
    expect(user).toHaveProperty(field);
    expect(typeof user[field]).toBe(
      expectedType,
      `user.${field} should be a ${expectedType}, got ${typeof user[field]}`,
    );
  });

  // id must be a positive integer
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.id).toBeGreaterThan(0);

  // name must be non-empty
  expect(user.name.trim().length).toBeGreaterThan(0);

  // email must contain "@" and at least one "." after the "@"
  expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);

  // Schema must not contain unexpected extra keys (strict shape check)
  const actualKeys = Object.keys(user).sort();
  const expectedKeys = Object.keys(USER_SCHEMA).sort();
  expect(actualKeys).toEqual(expectedKeys);
}

// ─── test data (mirrors app.js) ──────────────────────────────────────────────

const EXPECTED_USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ─── suite 1: happy path ─────────────────────────────────────────────────────

describe('GET /users – happy path', () => {
  let response;

  // Make a single request and share it across all tests in this suite
  // to avoid redundant network round-trips.
  beforeAll(async () => {
    response = await request(app).get('/users');
  });

  test('responds with HTTP 200 OK', () => {
    expect(response.status).toBe(200);
  });

  test('returns a JSON array', () => {
    expect(Array.isArray(response.body)).toBe(true);
  });

  test('returns the correct number of users', () => {
    expect(response.body).toHaveLength(EXPECTED_USERS.length);
  });

  test('returns Alice as the first user', () => {
    expect(response.body[0]).toEqual(EXPECTED_USERS[0]);
  });

  test('returns Bob as the second user', () => {
    expect(response.body[1]).toEqual(EXPECTED_USERS[1]);
  });

  test('returns the full user list with correct data', () => {
    expect(response.body).toEqual(EXPECTED_USERS);
  });

  test('user ids are unique across the list', () => {
    const ids = response.body.map((u) => u.id);
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  test('user emails are unique across the list', () => {
    const emails = response.body.map((u) => u.email);
    const uniqueEmails = new Set(emails);
    expect(uniqueEmails.size).toBe(emails.length);
  });
});

// ─── suite 2: response schema validation ─────────────────────────────────────

describe('GET /users – response schema', () => {
  let users;

  beforeAll(async () => {
    const response = await request(app).get('/users');
    users = response.body;
  });

  test('response body is an array', () => {
    expect(Array.isArray(users)).toBe(true);
  });

  test('array is non-empty', () => {
    expect(users.length).toBeGreaterThan(0);
  });

  test('every user object conforms to the expected schema', () => {
    users.forEach((user, index) => {
      try {
        assertUserSchema(user);
      } catch (err) {
        // Re-throw with position context so failures are easy to locate
        throw new Error(`Schema violation at users[${index}]: ${err.message}`);
      }
    });
  });

  test('user id is a positive integer', () => {
    users.forEach((user) => {
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });

  test('user name is a non-empty string', () => {
    users.forEach((user) => {
      expect(typeof user.name).toBe('string');
      expect(user.name.trim()).not.toBe('');
    });
  });

  test('user email matches a valid email pattern', () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    users.forEach((user) => {
      expect(user.email).toMatch(emailRegex);
    });
  });

  test('user objects contain no extra unexpected fields', () => {
    const allowedKeys = Object.keys(USER_SCHEMA).sort();
    users.forEach((user) => {
      expect(Object.keys(user).sort()).toEqual(allowedKeys);
    });
  });

  test('user id field is of type number, not a numeric string', () => {
    users.forEach((user) => {
      expect(typeof user.id).toBe('number');
    });
  });
});

// ─── suite 3: error handling ─────────────────────────────────────────────────

describe('GET /users – error handling', () => {
  test('returns 404 for an unknown route', async () => {
    const response = await request(app).get('/unknown-route');
    expect(response.status).toBe(404);
  });

  test('returns 404 for a similar but wrong route (/user, without the s)', async () => {
    const response = await request(app).get('/user');
    expect(response.status).toBe(404);
  });

  test('returns 404 for a route with an unexpected path segment (/users/1)', async () => {
    const response = await request(app).get('/users/1');
    expect(response.status).toBe(404);
  });

  test('POST /users returns 404 (method not registered)', async () => {
    const response = await request(app).post('/users').send({ name: 'Charlie' });
    expect(response.status).toBe(404);
  });

  test('PUT /users returns 404 (method not registered)', async () => {
    const response = await request(app).put('/users').send({ name: 'Charlie' });
    expect(response.status).toBe(404);
  });

  test('DELETE /users returns 404 (method not registered)', async () => {
    const response = await request(app).delete('/users');
    expect(response.status).toBe(404);
  });

  test('PATCH /users returns 404 (method not registered)', async () => {
    const response = await request(app).patch('/users');
    expect(response.status).toBe(404);
  });

  describe('simulated handler failure', () => {
    /**
     * Replace the real route with one that throws, verify the server
     * responds with 500, then restore the original handler so later
     * tests are unaffected.
     */

    let originalStack;

    beforeEach(() => {
      // Deep-copy the route stack so we can fully restore it
      originalStack = [...app._router.stack];

      // Inject a failing route at the FRONT of the stack so it takes
      // priority over the real /users handler
      app.get('/users', (_req, _res, next) => {
        next(new Error('Simulated internal server error'));
      });
    });

    afterEach(() => {
      // Restore the original router stack
      app._router.stack = originalStack;
    });

    test('responds with HTTP 500 when the handler throws an unhandled error', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(500);
    });
  });
});

// ─── suite 4: HTTP contract (headers & content-type) ─────────────────────────

describe('GET /users – HTTP contract', () => {
  let response;

  beforeAll(async () => {
    response = await request(app).get('/users');
  });

  test('Content-Type header is application/json', () => {
    expect(response.headers['content-type']).toMatch(/application\/json/);
  });

  test('response body can be parsed as valid JSON', () => {
    // supertest already parses it, but verify the raw text round-trips
    expect(() => JSON.parse(JSON.stringify(response.body))).not.toThrow();
  });

  test('responds to requests that explicitly accept application/json', async () => {
    const res = await request(app)
      .get('/users')
      .set('Accept', 'application/json');
    expect(res.status).toBe(200);
    expect(res.headers['content-type']).toMatch(/application\/json/);
  });

  test('responds correctly even when Accept header is wildcard */*', async () => {
    const res = await request(app).get('/users').set('Accept', '*/*');
    expect(res.status).toBe(200);
    expect(Array.isArray(res.body)).toBe(true);
  });

  test('response is not empty (Content-Length or Transfer-Encoding present)', () => {
    const hasLength = 'content-length' in response.headers;
    const hasTransferEncoding = 'transfer-encoding' in response.headers;
    expect(hasLength || hasTransferEncoding).toBe(true);
  });

  test('does not expose internal server details via X-Powered-By', () => {
    // Express sets X-Powered-By: Express by default; confirm it is either
    // absent (disabled for security) or not leaking stack details beyond "Express".
    const xPoweredBy = response.headers['x-powered-by'];
    if (xPoweredBy !== undefined) {
      expect(xPoweredBy).toMatch(/^express$/i);
    }
  });
});

