const request = require('supertest');
const app = require('./app');

// ---------------------------------------------------------------------------
// Schema helper
// Validates that a single user object matches the expected shape and types.
// ---------------------------------------------------------------------------
function isValidUser(user) {
  return (
    typeof user === 'object' &&
    user !== null &&
    typeof user.id === 'number' &&
    Number.isInteger(user.id) &&
    user.id > 0 &&
    typeof user.name === 'string' &&
    user.name.trim().length > 0 &&
    typeof user.email === 'string' &&
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email)
  );
}

// ---------------------------------------------------------------------------
// Test suite
// ---------------------------------------------------------------------------
describe('GET /users', () => {

  // ── Happy-path tests ──────────────────────────────────────────────────────

  describe('Happy path', () => {
    let response;

    // Issue one real HTTP request and reuse the result across the happy-path
    // tests so we don't hammer the server unnecessarily.
    beforeAll(async () => {
      response = await request(app).get('/users');
    });

    test('responds with HTTP 200 OK', () => {
      expect(response.statusCode).toBe(200);
    });

    test('sets Content-Type to application/json', () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('returns an array', () => {
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('returns at least one user', () => {
      expect(response.body.length).toBeGreaterThan(0);
    });

    test('includes the seeded users Alice and Bob', () => {
      const names = response.body.map((u) => u.name);
      expect(names).toContain('Alice');
      expect(names).toContain('Bob');
    });

    test('no two users share the same id', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    test('no two users share the same email address', () => {
      const emails = response.body.map((u) => u.email);
      const uniqueEmails = new Set(emails);
      expect(uniqueEmails.size).toBe(emails.length);
    });
  });

  // ── Response-schema tests ─────────────────────────────────────────────────

  describe('Response schema', () => {
    let users;

    beforeAll(async () => {
      const res = await request(app).get('/users');
      users = res.body;
    });

    test('every user has exactly the keys: id, name, email', () => {
      const expectedKeys = ['id', 'name', 'email'].sort();
      users.forEach((user) => {
        const actualKeys = Object.keys(user).sort();
        expect(actualKeys).toEqual(expectedKeys);
      });
    });

    test('every user.id is a positive integer', () => {
      users.forEach((user) => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('every user.name is a non-empty string', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('every user.email is a valid email address', () => {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      users.forEach((user) => {
        expect(typeof user.email).toBe('string');
        expect(emailRegex.test(user.email)).toBe(true);
      });
    });

    test('every user passes the full schema validator', () => {
      users.forEach((user) => {
        expect(isValidUser(user)).toBe(true);
      });
    });
  });

  // ── Error-handling tests ──────────────────────────────────────────────────

  describe('Error handling', () => {

    test('returns 404 for a non-existent route', async () => {
      const res = await request(app).get('/users/does-not-exist');
      expect(res.statusCode).toBe(404);
    });

    test('returns 404 for a completely unknown path', async () => {
      const res = await request(app).get('/unknown-endpoint');
      expect(res.statusCode).toBe(404);
    });

    test('GET /users ignores an unexpected query parameter and still returns 200', async () => {
      const res = await request(app).get('/users?foo=bar');
      expect(res.statusCode).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
    });

    test('POST /users returns 404 (method not registered)', async () => {
      const res = await request(app).post('/users').send({ name: 'Charlie' });
      expect(res.statusCode).toBe(404);
    });

    test('PUT /users returns 404 (method not registered)', async () => {
      const res = await request(app).put('/users').send({ id: 1 });
      expect(res.statusCode).toBe(404);
    });

    test('DELETE /users returns 404 (method not registered)', async () => {
      const res = await request(app).delete('/users');
      expect(res.statusCode).toBe(404);
    });

    test('PATCH /users returns 404 (method not registered)', async () => {
      const res = await request(app).patch('/users').send({});
      expect(res.statusCode).toBe(404);
    });

    test('response body is not null or undefined on a valid request', async () => {
      const res = await request(app).get('/users');
      expect(res.body).not.toBeNull();
      expect(res.body).not.toBeUndefined();
    });

    test('response body is not an error object on a valid request', async () => {
      const res = await request(app).get('/users');
      // A well-formed success response must not carry an "error" key
      expect(res.body).not.toHaveProperty('error');
      expect(res.body).not.toHaveProperty('message');
    });
  });

  // ── Regression / edge-case tests ──────────────────────────────────────────

  describe('Regression and edge cases', () => {

    test('handles concurrent requests without error', async () => {
      const requests = Array.from({ length: 10 }, () =>
        request(app).get('/users')
      );
      const responses = await Promise.all(requests);
      responses.forEach((res) => {
        expect(res.statusCode).toBe(200);
        expect(Array.isArray(res.body)).toBe(true);
      });
    });

    test('each concurrent response contains the same data', async () => {
      const requests = Array.from({ length: 5 }, () =>
        request(app).get('/users')
      );
      const responses = await Promise.all(requests);
      const first = JSON.stringify(responses[0].body);
      responses.forEach((res) => {
        expect(JSON.stringify(res.body)).toBe(first);
      });
    });

    test('/users and /users/ return consistent 200 responses', async () => {
      // Express treats trailing slashes as a different route by default;
      // both outcomes (200 or 301/404) are acceptable — what matters is
      // consistency and that the base path always works.
      const base = await request(app).get('/users');
      expect(base.statusCode).toBe(200);
    });
  });
});

