/**
 * Test suite for the /users endpoint in app.js
 *
 * Dependencies (install before running):
 *   npm install --save-dev jest supertest
 *
 * Run with:
 *   npx jest app.test.js          (single run)
 *   npx jest --watch app.test.js  (watch mode)
 *   npx jest --coverage           (with coverage report)
 */

const request = require('supertest');
const app = require('./app');

// ─── Constants ────────────────────────────────────────────────────────────────

const USERS_ENDPOINT = '/users';

/**
 * The schema every user object in the response must satisfy.
 * Centralised here so that the schema test and the field-level
 * assertions always stay in sync.
 */
const USER_SCHEMA = {
  requiredKeys: ['id', 'name', 'email'],
  types: {
    id: 'number',
    name: 'string',
    email: 'string',
  },
  // Minimal structural rules expressed as validator functions.
  validators: {
    id: (v) => Number.isInteger(v) && v > 0,
    name: (v) => v.trim().length > 0,
    email: (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),
  },
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Assert that `obj` conforms to USER_SCHEMA.
 * Returns an array of human-readable violation messages (empty = valid).
 */
function validateUserSchema(obj) {
  const violations = [];

  // 1. Must be a plain object
  if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) {
    return ['User must be a non-null plain object'];
  }

  // 2. Required keys must be present
  for (const key of USER_SCHEMA.requiredKeys) {
    if (!(key in obj)) {
      violations.push(`Missing required key: "${key}"`);
    }
  }

  // 3. Type checks
  for (const [key, expectedType] of Object.entries(USER_SCHEMA.types)) {
    if (key in obj && typeof obj[key] !== expectedType) {
      violations.push(
        `"${key}" should be ${expectedType}, got ${typeof obj[key]}`
      );
    }
  }

  // 4. Value-level validators
  for (const [key, validate] of Object.entries(USER_SCHEMA.validators)) {
    if (key in obj && !validate(obj[key])) {
      violations.push(`"${key}" failed value validation (value: ${JSON.stringify(obj[key])})`);
    }
  }

  // 5. No unexpected extra keys
  const unexpected = Object.keys(obj).filter(
    (k) => !USER_SCHEMA.requiredKeys.includes(k)
  );
  if (unexpected.length > 0) {
    violations.push(`Unexpected keys found: ${unexpected.map((k) => `"${k}"`).join(', ')}`);
  }

  return violations;
}

// ─── Test suite ───────────────────────────────────────────────────────────────

describe('GET /users', () => {

  // ── Happy path ──────────────────────────────────────────────────────────────

  describe('Happy path', () => {
    let response;

    // Make a single real HTTP request and reuse it across assertions in this
    // block, keeping the suite fast and the logs clean.
    beforeAll(async () => {
      response = await request(app).get(USERS_ENDPOINT);
    });

    it('should return HTTP 200 OK', () => {
      expect(response.statusCode).toBe(200);
    });

    it('should set Content-Type to application/json', () => {
      // Supertest normalises the header value; check for the mime type prefix.
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    it('should return a non-empty array', () => {
      expect(Array.isArray(response.body)).toBe(true);
      expect(response.body.length).toBeGreaterThan(0);
    });

    it('should return exactly 2 users', () => {
      expect(response.body).toHaveLength(2);
    });

    it('should include Alice as the first user', () => {
      const alice = response.body[0];
      expect(alice).toMatchObject({
        id: 1,
        name: 'Alice',
        email: 'alice@example.com',
      });
    });

    it('should include Bob as the second user', () => {
      const bob = response.body[1];
      expect(bob).toMatchObject({
        id: 2,
        name: 'Bob',
        email: 'bob@example.com',
      });
    });

    it('should return unique IDs for all users', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    it('should return unique email addresses for all users', () => {
      const emails = response.body.map((u) => u.email);
      const uniqueEmails = new Set(emails);
      expect(uniqueEmails.size).toBe(emails.length);
    });
  });

  // ── Response schema validation ───────────────────────────────────────────────

  describe('Response schema', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get(USERS_ENDPOINT);
      users = response.body;
    });

    it('should return an array at the top level', () => {
      expect(Array.isArray(users)).toBe(true);
    });

    it('every user object should contain exactly the required keys', () => {
      users.forEach((user, index) => {
        const violations = validateUserSchema(user);
        expect(violations).toEqual(
          // Custom failure message lists every violation for easy debugging
          expect.arrayContaining([])
        );
        if (violations.length > 0) {
          throw new Error(
            `User at index ${index} has schema violations:\n  • ${violations.join('\n  • ')}`
          );
        }
      });
    });

    it('"id" should be a positive integer for every user', () => {
      users.forEach((user, index) => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    it('"name" should be a non-empty string for every user', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    it('"email" should be a valid email address for every user', () => {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      users.forEach((user) => {
        expect(typeof user.email).toBe('string');
        expect(user.email).toMatch(emailRegex);
      });
    });

    it('should match the full expected snapshot', () => {
      // Snapshot test acts as a change-detector: any future modification to
      // the payload will surface here, prompting a deliberate review.
      expect(users).toMatchInlineSnapshot(`
        [
          {
            "email": "alice@example.com",
            "id": 1,
            "name": "Alice",
          },
          {
            "email": "bob@example.com",
            "id": 2,
            "name": "Bob",
          },
        ]
      `);
    });
  });

  // ── Error-handling ───────────────────────────────────────────────────────────

  describe('Error handling', () => {

    it('should return 404 for an unknown route', async () => {
      const response = await request(app).get('/users/unknown-route');
      expect(response.statusCode).toBe(404);
    });

    it('should ignore unexpected query parameters and still return 200', async () => {
      const response = await request(app)
        .get(USERS_ENDPOINT)
        .query({ foo: 'bar', page: 99 });
      expect(response.statusCode).toBe(200);
      // Payload should be unaffected
      expect(Array.isArray(response.body)).toBe(true);
      expect(response.body.length).toBeGreaterThan(0);
    });

    it('should return 404 for a POST to /users (method not registered)', async () => {
      const response = await request(app)
        .post(USERS_ENDPOINT)
        .send({ name: 'Charlie', email: 'charlie@example.com' });
      expect(response.statusCode).toBe(404);
    });

    it('should return 404 for a PUT to /users (method not registered)', async () => {
      const response = await request(app).put(USERS_ENDPOINT).send({});
      expect(response.statusCode).toBe(404);
    });

    it('should return 404 for a DELETE to /users (method not registered)', async () => {
      const response = await request(app).delete(USERS_ENDPOINT);
      expect(response.statusCode).toBe(404);
    });

    it('should return 404 for a PATCH to /users (method not registered)', async () => {
      const response = await request(app).patch(USERS_ENDPOINT).send({});
      expect(response.statusCode).toBe(404);
    });

    describe('Simulated internal server error', () => {
      let originalGet;

      // Temporarily replace the express route handler so that it throws,
      // simulating an upstream dependency failure (e.g. a crashed database).
      beforeEach(() => {
        // Locate the layer for GET /users and monkey-patch its handle.
        originalGet = app._router.stack.find(
          (layer) =>
            layer.route &&
            layer.route.path === USERS_ENDPOINT &&
            layer.route.methods.get
        );

        if (originalGet) {
          originalGet.route.stack[0]._originalHandle =
            originalGet.route.stack[0].handle;
          originalGet.route.stack[0].handle = (req, res, next) => {
            next(new Error('Simulated database failure'));
          };
        }
      });

      afterEach(() => {
        // Restore the original handler so other tests are unaffected.
        if (
          originalGet &&
          originalGet.route.stack[0]._originalHandle
        ) {
          originalGet.route.stack[0].handle =
            originalGet.route.stack[0]._originalHandle;
          delete originalGet.route.stack[0]._originalHandle;
        }
      });

      it('should return HTTP 500 when the route handler throws', async () => {
        const response = await request(app).get(USERS_ENDPOINT);
        expect(response.statusCode).toBe(500);
      });
    });
  });

  // ── Concurrent requests ──────────────────────────────────────────────────────

  describe('Concurrency', () => {
    it('should handle multiple simultaneous requests and return consistent data', async () => {
      const CONCURRENT = 10;
      const responses = await Promise.all(
        Array.from({ length: CONCURRENT }, () =>
          request(app).get(USERS_ENDPOINT)
        )
      );

      responses.forEach((res) => {
        expect(res.statusCode).toBe(200);
        expect(res.body).toHaveLength(2);
        expect(res.body[0]).toMatchObject({ id: 1, name: 'Alice' });
        expect(res.body[1]).toMatchObject({ id: 2, name: 'Bob' });
      });
    });
  });

});

