const express = require('express');
const app = express();

app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// In-memory user store — makes it straightforward to inject errors in tests.
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

let simulateDbError = false; // toggled by tests via module export

app.get('/users', (req, res) => {
  if (simulateDbError) {
    return res.status(500).json({ error: 'Internal Server Error', message: 'Database unavailable' });
  }
  res.json(users);
});

app.get('/users/:id', (req, res) => {
  if (simulateDbError) {
    return res.status(500).json({ error: 'Internal Server Error', message: 'Database unavailable' });
  }

  const id   = parseInt(req.params.id, 10);
  const user = users.find((u) => u.id === id);

  if (!user) {
    return res.status(404).json({ error: 'Not Found', message: `User ${id} not found` });
  }

  res.json(user);
});

// Only start listening when this file is run directly (not imported by tests).
if (require.main === module) {
  app.listen(3000, () => console.log('Server running on port 3000'));
}

module.exports = { app, setSimulateDbError: (v) => { simulateDbError = v; } };

