 * correct JavaScript type, and contains NO extra unexpected keys.
 */
function assertUserSchema(obj) {
  // Required fields + types
  USER_SCHEMA.forEach(([field, type]) => {
    expect(obj).toHaveProperty(field);
    expect(typeof obj[field]).toBe(type);
  });

  // No extra keys
  const expectedKeys = USER_SCHEMA.map(([f]) => f);
  const actualKeys   = Object.keys(obj);
  expect(actualKeys.sort()).toEqual(expectedKeys.sort());
}

/**
 * Assert that an email string is (loosely) valid.
 */
function assertValidEmail(email) {
