/**
 * Test suite for the /users endpoint in app.js
 *
 * Dependencies (install before running):
 *   npm install --save-dev jest supertest
 *
 * Run tests:
 *   npx jest              (all tests)
 *   npx jest --verbose    (with per-test labels)
 *   npx jest --coverage   (with coverage report)
 */

const request = require('supertest');
const app = require('./app');

// ─── Schema helper ────────────────────────────────────────────────────────────

/**
 * Validates that a single user object matches the expected shape:
 *   { id: number, name: string, email: string }
 *
 * Returns an array of human-readable violation strings (empty = valid).
 */
function validateUserSchema(user) {
  const violations = [];

  if (typeof user !== 'object' || user === null || Array.isArray(user)) {
    violations.push('user must be a non-null object');
    return violations; // no point checking fields on a non-object
  }

  // id
  if (!('id' in user)) {
    violations.push('missing required field: id');
  } else if (typeof user.id !== 'number' || !Number.isInteger(user.id) || user.id <= 0) {
    violations.push(`id must be a positive integer, got: ${JSON.stringify(user.id)}`);
  }

  // name
  if (!('name' in user)) {
    violations.push('missing required field: name');
  } else if (typeof user.name !== 'string' || user.name.trim() === '') {
    violations.push(`name must be a non-empty string, got: ${JSON.stringify(user.name)}`);
  }

  // email — basic RFC-like sanity check
  if (!('email' in user)) {
    violations.push('missing required field: email');
  } else if (typeof user.email !== 'string') {
    violations.push(`email must be a string, got: ${JSON.stringify(user.email)}`);
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(user.email)) {
    violations.push(`email does not look valid: ${JSON.stringify(user.email)}`);
  }

  // No extra / unexpected keys
  const allowed = new Set(['id', 'name', 'email']);
  const extra = Object.keys(user).filter((k) => !allowed.has(k));
  if (extra.length > 0) {
    violations.push(`unexpected field(s): ${extra.join(', ')}`);
  }

  return violations;
}

// ─── Test suite ───────────────────────────────────────────────────────────────

describe('GET /users', () => {

  // ── 1. Happy path ──────────────────────────────────────────────────────────

  describe('happy path', () => {

    test('responds with HTTP 200 OK', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(200);
    });

    test('responds with Content-Type application/json', async () => {
      const res = await request(app).get('/users');
      expect(res.headers['content-type']).toMatch(/application\/json/);
    });

    test('returns a non-empty array', async () => {
      const res = await request(app).get('/users');
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBeGreaterThan(0);
    });

    test('returns exactly 2 users', async () => {
      const res = await request(app).get('/users');
      expect(res.body).toHaveLength(2);
    });

    test('returns Alice as the first user', async () => {
      const res = await request(app).get('/users');
      expect(res.body[0]).toMatchObject({
        id: 1,
        name: 'Alice',
        email: 'alice@example.com',
      });
    });

    test('returns Bob as the second user', async () => {
      const res = await request(app).get('/users');
      expect(res.body[1]).toMatchObject({
        id: 2,
        name: 'Bob',
        email: 'bob@example.com',
      });
    });

    test('all user ids are unique', async () => {
      const res = await request(app).get('/users');
      const ids = res.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    test('all user emails are unique', async () => {
      const res = await request(app).get('/users');
      const emails = res.body.map((u) => u.email);
      const uniqueEmails = new Set(emails);
      expect(uniqueEmails.size).toBe(emails.length);
    });

  });

  // ── 2. Schema validation ───────────────────────────────────────────────────

  describe('response schema', () => {

    test('every user passes the full schema check', async () => {
      const res = await request(app).get('/users');

      res.body.forEach((user, index) => {
        const violations = validateUserSchema(user);
        expect(violations).toEqual(
          /* each user's violations array should be empty */
          [],
          /* surfaced in the failure message if the assertion fails */
          `user at index ${index} has schema violations: ${violations.join('; ')}`
        );
      });
    });

    test('each user has exactly the fields: id, name, email — no more, no less', async () => {
      const res = await request(app).get('/users');
      const expectedKeys = ['id', 'name', 'email'];

      res.body.forEach((user, index) => {
        const actualKeys = Object.keys(user).sort();
        expect(actualKeys).toEqual(
          [...expectedKeys].sort(),
          `user at index ${index} has unexpected keys: ${actualKeys}`
        );
      });
    });

    test('id is a positive integer for every user', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user, index) => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('name is a non-empty string for every user', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('email matches a valid email format for every user', async () => {
      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const res = await request(app).get('/users');
      res.body.forEach((user) => {
        expect(typeof user.email).toBe('string');
        expect(user.email).toMatch(EMAIL_RE);
      });
    });

    test('snapshot — full response body matches stored snapshot', async () => {
      const res = await request(app).get('/users');
      expect(res.body).toMatchSnapshot();
    });

  });

  // ── 3. Error / edge case handling ──────────────────────────────────────────

  describe('error handling', () => {

    test('responds with 404 for a missing sub-resource /users/999', async () => {
      const res = await request(app).get('/users/999');
      // The app has no /users/:id route, so Express returns 404 by default.
      expect(res.statusCode).toBe(404);
    });

    test('GET /users is idempotent — two sequential calls return identical data', async () => {
      const first  = await request(app).get('/users');
      const second = await request(app).get('/users');
      expect(first.body).toEqual(second.body);
    });

    test('responds with 404 for a similar but wrong path /user (no "s")', async () => {
      const res = await request(app).get('/user');
      expect(res.statusCode).toBe(404);
    });

    test('POST /users is not supported and returns 404', async () => {
      const res = await request(app).post('/users').send({ name: 'Eve', email: 'eve@example.com' });
      // The app defines no POST handler; Express default is 404.
      expect(res.statusCode).toBe(404);
    });

    test('PUT /users is not supported and returns 404', async () => {
      const res = await request(app).put('/users');
      expect(res.statusCode).toBe(404);
    });

    test('DELETE /users is not supported and returns 404', async () => {
      const res = await request(app).delete('/users');
      expect(res.statusCode).toBe(404);
    });

    describe('simulated server error via route override', () => {
      let crashApp;

      beforeAll(() => {
        // Build a minimal, isolated express app that mirrors app.js but
        // with /users wired to throw, so we can verify 500 behaviour
        // without touching the real app instance.
        const express = require('express');
        crashApp = express();

        crashApp.get('/users', (_req, _res, next) => {
          next(new Error('Simulated database failure'));
        });

        // Express error-handling middleware (4 args)
        crashApp.use((err, _req, res, _next) => {
          res.status(500).json({ error: err.message });
        });
      });

      test('returns 500 and a JSON error body when the handler throws', async () => {
        const res = await request(crashApp).get('/users');
        expect(res.statusCode).toBe(500);
        expect(res.body).toHaveProperty('error');
        expect(typeof res.body.error).toBe('string');
        expect(res.body.error.length).toBeGreaterThan(0);
      });

      test('500 response body contains the error message', async () => {
        const res = await request(crashApp).get('/users');
        expect(res.body.error).toBe('Simulated database failure');
      });
    });

  });

});

