/**
 * app.test.js
 *
 * Unit / integration tests for the Express application defined in app.js.
 * Focuses on the GET /users endpoint, covering:
 *   1. Happy-path behaviour  – correct status, body shape, and data.
 *   2. Response-schema validation – every field of every user object is present
 *      and has the right type (acts as a lightweight contract test).
 *   3. Error-handling / edge cases – wrong method, wrong path, missing Accept
 *      header, concurrent requests, etc.
 *
 * Dependencies (install before running):
 *   npm install --save-dev jest supertest
 *
 * Run:
 *   npx jest           # or: npm test  (after the script is wired up)
 */

const request = require('supertest');
const app     = require('./app');

// ─────────────────────────────────────────────────────────────────────────────
// Shared schema validator
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Asserts that a single user object conforms to the expected schema.
 *
 * Expected shape:
 *   {
 *     id:    number   (positive integer)
 *     name:  string   (non-empty)
 *     email: string   (non-empty, contains "@")
 *   }
 *
 * Keeping this as a plain helper (rather than a matcher plugin) keeps the
 * file self-contained and easy to read.
 *
 * @param {unknown} user - The value to validate.
 */
function assertValidUserSchema(user) {
  // Must be a plain object, not null / array / primitive
  expect(user).toBeDefined();
  expect(typeof user).toBe('object');
  expect(user).not.toBeNull();
  expect(Array.isArray(user)).toBe(false);

