/**
 * Test suite for app.js — /users endpoint
 *
 * Coverage:
 *  1. Happy path        – correct status codes, body shape, and field values
 *  2. Error handling    – simulated server-side failures (500), unknown routes (404)
 *  3. Schema validation – every user object in the response matches the expected schema
 *
 * Dependencies:
 *   supertest  – fires real HTTP requests against the Express app without
 *                binding to a port, so tests are fast and isolated.
 *   jest       – test runner, assertion library, and mocking framework.
 *
 * Run:
 *   npm test               (plain)
 *   npm run test:verbose   (with per-test output)
 *   npm run test:coverage  (with coverage report)
 */

const request = require('supertest');
const express = require('express');

// ─── import the app under test ───────────────────────────────────────────────
// app.js calls app.listen(), but supertest manages its own port so there is no
// conflict.  We keep a reference so we can swap out route handlers in tests
// that exercise error paths.
const app = require('./app');

// ─── shared schema helper ─────────────────────────────────────────────────────
/**
 * Asserts that `user` conforms to the User schema:
 *
 *  {
 *    id:    number  (positive integer)
 *    name:  string  (non-empty)
 *    email: string  (basic RFC-5321 shape: local@domain.tld)
 *  }
 *
 * Extracted into a helper so every test that touches schema can reuse it
 * without duplicating assertions.
 *
 * @param {unknown} user - The value to validate.
 */
function assertUserSchema(user) {
  // Top-level type
  expect(typeof user).toBe('object');
  expect(user).not.toBeNull();

  // ── id ──────────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('id');
  expect(typeof user.id).toBe('number');
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.id).toBeGreaterThan(0);

  // ── name ────────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('name');
  expect(typeof user.name).toBe('string');
  expect(user.name.trim().length).toBeGreaterThan(0);

  // ── email ───────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('email');
  expect(typeof user.email).toBe('string');
  // Basic email pattern: something@something.something
  expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);

  // ── no unexpected extra fields ───────────────────────────────────────────────
  const allowedKeys = new Set(['id', 'name', 'email']);
  const extraKeys = Object.keys(user).filter((k) => !allowedKeys.has(k));
  expect(extraKeys).toHaveLength(0);
}

// =============================================================================
// 1. HAPPY PATH
// =============================================================================
describe('GET /users — happy path', () => {
  let response;

  // Fire the request once and reuse it across all expectations in this block —
  // avoids redundant network round-trips.
  beforeAll(async () => {
    response = await request(app).get('/users');
  });

  // ── HTTP-level checks ────────────────────────────────────────────────────────
  it('responds with HTTP 200 OK', () => {
    expect(response.statusCode).toBe(200);
  });

  it('sets Content-Type to application/json', () => {
    expect(response.headers['content-type']).toMatch(/application\/json/);
  });

  // ── Body-level checks ────────────────────────────────────────────────────────
  it('returns a non-empty array', () => {
    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body.length).toBeGreaterThan(0);
  });

  it('returns exactly 2 users', () => {
    expect(response.body).toHaveLength(2);
  });

  // ── Field-level checks ───────────────────────────────────────────────────────
  it('returns Alice as the first user with correct fields', () => {
    const alice = response.body[0];
    expect(alice).toEqual({
      id: 1,
      name: 'Alice',
      email: 'alice@example.com',
    });
  });

  it('returns Bob as the second user with correct fields', () => {
    const bob = response.body[1];
    expect(bob).toEqual({
      id: 2,
      name: 'Bob',
      email: 'bob@example.com',
    });
  });

  it('returns users with unique ids', () => {
    const ids = response.body.map((u) => u.id);
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  it('returns users with unique emails', () => {
    const emails = response.body.map((u) => u.email);
    const uniqueEmails = new Set(emails);
    expect(uniqueEmails.size).toBe(emails.length);
  });
});

// =============================================================================
// 2. ERROR HANDLING
// =============================================================================
describe('GET /users — error handling', () => {
